using System.Text;

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace Gen;

/// <summary>
/// Emits a Greet method for every partial class marked [Greetable]. Deliberately input-driven:
/// adding or removing an attribute changes generated output, which is what the freshness tests
/// assert on.
/// </summary>
[Generator(LanguageNames.CSharp)]
public sealed class GreetingGenerator : IIncrementalGenerator
{
	private const string AttributeSource = @"// <auto-generated/>
namespace Gen
{
    [System.AttributeUsage(System.AttributeTargets.Class)]
    internal sealed class GreetableAttribute : System.Attribute
    {
        public GreetableAttribute(string greeting) => Greeting = greeting;
        public string Greeting { get; }
    }
}
";

	public void Initialize(IncrementalGeneratorInitializationContext context)
	{
		context.RegisterPostInitializationOutput(
			ctx => ctx.AddSource("GreetableAttribute.g.cs", SourceText.From(AttributeSource, Encoding.UTF8)));

		var targets = context.SyntaxProvider.ForAttributeWithMetadataName(
			"Gen.GreetableAttribute",
			predicate: static (node, _) => node is ClassDeclarationSyntax,
			transform: static (ctx, _) =>
			{
				var symbol = (INamedTypeSymbol)ctx.TargetSymbol;
				var arguments = ctx.Attributes[0].ConstructorArguments;
				var greeting = arguments.Length > 0 && arguments[0].Value is string text ? text : "Hello";
				return (Namespace: symbol.ContainingNamespace.ToDisplayString(), Name: symbol.Name, Greeting: greeting);
			});

		context.RegisterSourceOutput(targets, static (ctx, target) =>
		{
			var source = $@"// <auto-generated/>
namespace {target.Namespace}
{{
    partial class {target.Name}
    {{
        public string Greet() => ""{target.Greeting}, from a source generator."";
    }}
}}
";
			ctx.AddSource($"{target.Name}.Greeting.g.cs", SourceText.From(source, Encoding.UTF8));
		});
	}
}
